from collections import deque

def coin_change(coins, amount):
    seen = {0}
    queue = deque([(0, 0)])            # (amount reached, coins used)
    while queue:
        a, used = queue.popleft()
        if a == amount:
            return used                # BFS: first arrival uses the fewest coins
        for c in coins:
            if a + c <= amount and a + c not in seen:
                seen.add(a + c)
                queue.append((a + c, used + 1))
    return -1

