def change(amount, coins):
    n = len(coins)
    dp = [[0] * (amount + 1) for _ in range(n + 1)]   # dp[i][a]: first i coins
    for i in range(n + 1):
        dp[i][0] = 1                   # one way to make 0: take nothing
    for i in range(1, n + 1):
        c = coins[i - 1]
        for a in range(1, amount + 1):
            dp[i][a] = dp[i - 1][a] + (dp[i][a - c] if a >= c else 0)   # skip c, or use it again
    return dp[n][amount]
